async fn require_permission(
    State(state): State<AppState>, req: Request, next: Next,
) -> Response {
    let principal = req.extensions().get::<Principal>().cloned();
    match principal {
        Some(p) if state.pdp.allowed(&p, req.method(), req.uri().path()) => next.run(req).await,
        _ => StatusCode::FORBIDDEN.into_response(),      // fail closed, no inner call
    }
}

let admin = Router::new()
    .route("/orders", get(list_orders))
    .route_layer(middleware::from_fn_with_state(state.clone(), require_permission));

