struct RequireRead;

impl<S> FromRequestParts<S> for RequireRead where S: Send + Sync {
    type Rejection = StatusCode;

    async fn from_request_parts(parts: &mut Parts, state: &S) -> Result<Self, Self::Rejection> {
        let principal = parts.extensions.get::<Principal>();
        let allowed = principal.map(|p| p.can("read")).unwrap_or(false);
        if allowed { Ok(RequireRead) } else { Err(StatusCode::FORBIDDEN) }
    }
}

